definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '10', artifactNumToKeepStr: '3'))
    timeout(time: 150, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
    // This Docker env's builders (BuildKit AND legacy, proven) do NOT use the
    // host image store, so base-derived images must resolve their parent FROM
    // the registry. deployment.py passes this through as --build-arg
    // BASE_REGISTRY, so android-sdk/conan-* do
    // FROM localhost:5001/johndoe6345789/metabuilder/base-apt:latest -- pulled
    // from Nexus, where base-apt is built and pushed first this run.
    BASE_REGISTRY = 'localhost:5001/johndoe6345789/metabuilder'
    // Route Conan deps through the pkgrepo cache (proxies conancenter onto the
    // host NVMe). 172.17.0.1 (docker0 gateway) is reachable from host- and bridge-network builds.
    CONAN_REMOTE = 'http://172.17.0.1:5002/conan'
    // Route pip deps (pip-deps base) through the pkgrepo pypi cache the same way.
    PIP_INDEX_URL = 'http://172.17.0.1:5002/pypi/simple/'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Acquire disk lock') {
      steps {
        // Best-effort cross-job advisory lock for this shared, disk-constrained
        // host: only ONE base build (metabuilder OR businessplanner) may run at
        // a time, else peak disk blows. The inspect-then-create race is
        // acceptable (base builds are long, infrequent, orchestrator-serialized).
        // docker-housekeeping also skips its prune while this volume exists.
        sh '''
          if docker volume inspect mb-base-running >/dev/null 2>&1; then
            echo "another base build holds the mb-base-running lock -- aborting to protect disk" >&2
            exit 1
          fi
          docker volume create mb-base-running >/dev/null
          touch .mb_lock_owned
        '''
        sh 'docker builder prune -f --filter until=48h || true'
      }
    }

    // Disk-safe SERIAL pipeline. Order matters: base-apt is built first and
    // kept resident because android-sdk / conan-cli / conan-media build
    // FROM metabuilder/base-apt:latest (local). node-deps and pip-deps have
    // no local dependents here, so they are pruned immediately. base-apt is
    // dropped at the very end. Peak disk ~= base-apt + one dependent.
    stage('Build+Push+Prune base images') {
      options { timeout(time: 140, unit: 'MINUTES') }
      steps {
        sh '''
          docker version
        '''
        script {
          def routine = ['apt', 'node-deps', 'pip-deps', 'android-sdk', 'conan-cli', 'conan-media']
          for (nm in routine) {
            def keep = (nm == 'apt') ? '1' : '0'
            stage("base: ${nm}") {
              catchError(message: "base ${nm} failed -- dependent apps skipped this cycle", buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
                withEnv(["BASE_BUILD_NAME=${nm}", "KEEP_LOCAL=${keep}"]) {
                  sh '''
                    set -e
                    cd deployment
                    python3 deployment.py build base "$BASE_BUILD_NAME"

                      python3 - <<'PY'
import json
import os
import subprocess
import sys

name = os.environ["BASE_BUILD_NAME"]
keep = os.environ.get("KEEP_LOCAL") == "1"

with open("cli/commands.json") as f:
    D = json.load(f)["definitions"]

local = D["base_images"][name]["tag"]
allimgs = D["nexus_images"]["base"] + D["nexus_images"].get("heavy", [])
short = None
for it in allimgs:
    if it["local"] == local:
        short = it["name"]
        break
if short is None:
    print("No Nexus mapping for " + local + " -- skipping push", file=sys.stderr)
    sys.exit(0)

registry = os.environ.get("NEXUS_REGISTRY", "localhost:5001")
slug = "johndoe6345789/metabuilder"
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()

if subprocess.run(["docker", "image", "inspect", local], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
    print("ERROR: " + local + " was not built; nothing to push", file=sys.stderr)
    sys.exit(1)

for version in (tag, "latest"):
    target = registry + "/" + slug + "/" + short + ":" + version
    subprocess.check_call(["docker", "tag", local, target])
    subprocess.check_call(["docker", "push", target])
    subprocess.run(["docker", "rmi", "-f", target], check=False)
print("Pushed " + slug + "/" + short + " (" + tag + ", latest)")

if keep:
    print("Kept local " + local + " (local dependents need it)")
else:
    repo = local.split(":")[0]
    listed = subprocess.run(["docker", "images", "--format", "{{.Repository}}:{{.Tag}}"], capture_output=True, text=True).stdout.splitlines()
    for ln in listed:
        if ln.split(":")[0] == repo:
            subprocess.run(["docker", "rmi", "-f", ln], check=False)
    subprocess.run(["docker", "builder", "prune", "-f", "--filter", "until=24h"], check=False)
    print("Pruned local " + repo + " (freed disk before next base)")
PY
                  '''
                }
              }
            }
          }
          stage('drop base-apt') {
            sh '''
              docker images --format '{{.Repository}}:{{.Tag}}' \
                | grep '^metabuilder/base-apt:' \
                | xargs -r docker rmi -f 2>/dev/null || true
              docker builder prune -f --filter until=24h || true
            '''
          }
        }
      }
    }
  }

  post {
    always {
      sh 'if [ -f .mb_lock_owned ]; then docker volume rm -f mb-base-running >/dev/null 2>&1 || true; echo "released mb-base-running lock"; fi'
      cleanWs()
    }
  }
}
